package org.xingmu.tv;
import android.app.Activity;import android.os.*;import android.content.*;import android.view.*;import android.webkit.*;import android.widget.*;import androidx.media3.common.*;import androidx.media3.exoplayer.*;import androidx.media3.ui.PlayerView;import java.util.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class PlayerActivity extends Activity {
 private final Handler handler=new Handler(Looper.getMainLooper());private final List<CatalogItem> items=new ArrayList<>();private int index,generation,retries;private ExoPlayer player;private PlayerView video;private WebView web;private TextView info;private FrameLayout screen;private boolean running;private View customView;private WebChromeClient.CustomViewCallback customCallback;private CatalogItem item;private View errorOverlay;private boolean completed;private int sourceIndex;private final Set<String> failedSources=new HashSet<>();private long bufferingSince,lastProgress,lastPosition=-1,lastSwitch;private WatchStore store;
 @Override public void onCreate(Bundle state){super.onCreate(state);store=new WatchStore(this);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);TvUi.full(this);ArrayList<String> ids=getIntent().getStringArrayListExtra("ids");try{Map<String,CatalogItem> all=new HashMap<>();for(CatalogItem i:new CatalogRepository(this).load())all.put(i.id,i);if(ids!=null)for(String id:ids)if(all.containsKey(id))items.add(all.get(id));}catch(Exception e){TvUi.toast(this,"内容加载失败");}if(items.isEmpty()){finish();return;}index=Math.max(0,Math.min(state==null?getIntent().getIntExtra("index",0):state.getInt("index",0),items.size()-1));}
 @Override protected void onStart(){super.onStart();running=true;if(!items.isEmpty())open();}
 private void open(){release();generation++;retries=0;completed=false;errorOverlay=null;failedSources.clear();bufferingSince=0;lastProgress=SystemClock.elapsedRealtime();lastPosition=-1;item=items.get(index);sourceIndex=Math.max(0,item.urls.indexOf(getSharedPreferences("settings",0).getString("best_"+item.id,item.url)));LinearLayout root=TvUi.col(this);root.setBackgroundColor(TvUi.BG);LinearLayout bar=TvUi.row(this);bar.setPadding(TvUi.dp(this,18),TvUi.dp(this,8),TvUi.dp(this,18),TvUi.dp(this,8));info=TvUi.text(this,item.title,16,TvUi.INK);info.setMaxLines(1);info.setEllipsize(android.text.TextUtils.TruncateAt.END);bar.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button options=TvUi.button(this,"选项");options.setOnClickListener(v->options());Button prev=TvUi.button(this,"上一项"),next=TvUi.button(this,"下一项"),back=TvUi.button(this,"返回");prev.setOnClickListener(v->switchItem(-1));next.setOnClickListener(v->switchItem(1));back.setOnClickListener(v->finish());if(getResources().getConfiguration().screenWidthDp<600){for(Button button:new Button[]{options,prev,next,back}){button.setTextSize(13);button.setMinWidth(0);button.setMinimumWidth(0);button.setPadding(10,8,10,8);}}bar.addView(options);bar.addView(prev);bar.addView(next);bar.addView(back);root.addView(bar);screen=new FrameLayout(this);root.addView(screen,new LinearLayout.LayoutParams(-1,0,1));TextView attribution=TvUi.text(this,item.license+(item.live()?" · 左右键 / 频道键切换":""),12,TvUi.MUTED);attribution.setPadding(16,6,16,6);root.addView(attribution);setContentView(root);TvUi.full(this);
 if(item.mode.equals("official"))openWeb();else openVideo();
 }
 private void openVideo(){final int token=generation;video=new PlayerView(this);screen.addView(video,new FrameLayout.LayoutParams(-1,-1));video.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);video.setControllerAutoShow(true);DefaultLoadControl buffers=new DefaultLoadControl.Builder().setBufferDurationsMs(15000,45000,1500,2500).build();player=new ExoPlayer.Builder(this).setLoadControl(buffers).setMediaSourceFactory(new androidx.media3.exoplayer.source.DefaultMediaSourceFactory(new androidx.media3.datasource.DefaultDataSource.Factory(this,new androidx.media3.datasource.DefaultHttpDataSource.Factory().setUserAgent("XingmuTV/1.1").setConnectTimeoutMs(8000).setReadTimeoutMs(12000)))).build();video.setPlayer(player);player.setAudioAttributes(new androidx.media3.common.AudioAttributes.Builder().setUsage(C.USAGE_MEDIA).setContentType(C.AUDIO_CONTENT_TYPE_MOVIE).build(),true);player.setHandleAudioBecomingNoisy(true);video.setResizeMode(getSharedPreferences("settings",0).getInt("resize",0));if(!item.live())player.setPlaybackSpeed(getSharedPreferences("settings",0).getFloat("speed",1f));player.addListener(new Player.Listener(){@Override public void onPlaybackStateChanged(int state){if(token!=generation)return;if(state==Player.STATE_READY){info.setText(item.title+(item.urls.size()>1?" · 源 "+(sourceIndex+1)+"/"+item.urls.size():""));bufferingSince=0;lastProgress=SystemClock.elapsedRealtime();getSharedPreferences("settings",0).edit().putString("best_"+item.id,item.urls.get(sourceIndex)).apply();if(errorOverlay!=null){screen.removeView(errorOverlay);errorOverlay=null;}store.watched(item.id);}if(state==Player.STATE_BUFFERING&&bufferingSince==0)bufferingSince=SystemClock.elapsedRealtime();if(state==Player.STATE_ENDED&&item.live())recover(token,"直播结束");if(state==Player.STATE_ENDED&&!item.live()){completed=true;store.position(item.id,0);if(getSharedPreferences("settings",0).getBoolean("autoplay",false)&&index+1<items.size())handler.post(()->{if(token==generation&&running)switchItem(1);});}}@Override public void onPlayerError(PlaybackException error){recover(token,"当前源暂时不可达");}});player.setMediaItem(media(item.urls.get(sourceIndex)));if(!item.live())player.seekTo(store.position(item.id));player.prepare();player.play();video.requestFocus();handler.postDelayed(new Runnable(){public void run(){if(token!=generation||!running||player==null)return;long now=SystemClock.elapsedRealtime();if(!item.live()&&!completed&&player.getPlaybackState()==Player.STATE_READY)store.position(item.id,player.getCurrentPosition());if(player.getCurrentPosition()!=lastPosition){if(player.isPlaying()&&lastPosition>=0&&player.getCurrentPosition()>lastPosition)retries=0;lastPosition=player.getCurrentPosition();lastProgress=now;}if(item.live()&&player.getPlayWhenReady()&&errorOverlay==null){if(player.getPlaybackState()==Player.STATE_BUFFERING&&bufferingSince!=0&&now-bufferingSince>=20000){bufferingSince=now;recover(token,"缓冲超时");}else if(player.isPlaying()&&now-lastProgress>=20000){lastProgress=now;recover(token,"播放停滞");}}handler.postDelayed(this,10000);}},10000);}
 private void openWeb(){try{web=new WebView(this);web.setBackgroundColor(0xff000000);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setUseWideViewPort(true);web.getSettings().setLoadWithOverviewMode(true);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebChromeClient(new WebChromeClient(){@Override public void onShowCustomView(View view,CustomViewCallback callback){if(customView!=null){callback.onCustomViewHidden();return;}customView=view;customCallback=callback;((android.view.ViewGroup)getWindow().getDecorView()).addView(view,new android.view.ViewGroup.LayoutParams(-1,-1));TvUi.full(PlayerActivity.this);}@Override public void onHideCustomView(){hideWebFullscreen();}});web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){if(item!=null&&item.url.equals(url))store.watched(item.id);}@Override public boolean shouldOverrideUrlLoading(WebView v,String url){return !CatalogParser.safeUrl(url);}@Override public void onReceivedError(WebView v,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())info.setText("官方页面不可达：请检查网络，或导入已授权直播流");}});screen.addView(web,new FrameLayout.LayoutParams(-1,-1));info.setText(item.title+" · 官方页面，可能需点击播放");web.loadUrl(item.url);web.requestFocus();}catch(RuntimeException e){showError("设备没有可用的 Android WebView，官方页面无法打开。请更新系统 WebView，或导入已授权的直接播放源。");}}
 private void showError(String message){if(errorOverlay!=null)screen.removeView(errorOverlay);LinearLayout panel=TvUi.col(this);panel.setGravity(Gravity.CENTER);panel.setBackgroundColor(TvUi.BG);panel.setPadding(36,24,36,24);TextView text=TvUi.text(this,message,19,TvUi.INK);text.setGravity(Gravity.CENTER);panel.addView(text);Button retry=TvUi.button(this,"重新加载"),next=TvUi.button(this,"换下一项");retry.setOnClickListener(v->{if(player!=null&&!item.mode.equals("official")){screen.removeView(panel);errorOverlay=null;retries=0;failedSources.clear();bufferingSince=SystemClock.elapsedRealtime();player.prepare();player.play();}else open();});next.setOnClickListener(v->switchItem(1));panel.addView(retry);panel.addView(next);errorOverlay=panel;screen.addView(panel,new FrameLayout.LayoutParams(-1,-1));retry.requestFocus();info.setText("播放暂不可用");}
 private void options(){String[] entries={store.favourite(item.id)?"取消收藏":"收藏此内容","画面比例","播放速度","从头播放","切换播放源"};new android.app.AlertDialog.Builder(this).setTitle(item.title).setItems(entries,(dialog,which)->{if(which==0){store.toggle(item.id);TvUi.toast(this,store.favourite(item.id)?"已收藏":"已取消收藏");}else if(player==null){TvUi.toast(this,"此设置仅适用于直接播放内容");}else if(which==1){int[] modes={0,4,3};new android.app.AlertDialog.Builder(this).setTitle("画面比例").setItems(new String[]{"原始比例","放大裁切","铺满画面"},(d,n)->{video.setResizeMode(modes[n]);getSharedPreferences("settings",0).edit().putInt("resize",modes[n]).apply();}).show();}else if(which==2){if(item.live()){TvUi.toast(this,"直播使用正常速度");return;}float[] speeds={.75f,1f,1.25f,1.5f,2f};new android.app.AlertDialog.Builder(this).setTitle("播放速度").setItems(new String[]{"0.75×","1×","1.25×","1.5×","2×"},(d,n)->{player.setPlaybackSpeed(speeds[n]);getSharedPreferences("settings",0).edit().putFloat("speed",speeds[n]).apply();}).show();}else if(which==3&&!item.live()){completed=false;player.seekTo(0);player.play();}else if(which==4){String[] labels=new String[item.urls.size()];for(int n=0;n<labels.length;n++)labels[n]="播放源 "+(n+1)+(n==sourceIndex?" · 当前":"");new android.app.AlertDialog.Builder(this).setTitle("选择此频道的播放源").setItems(labels,(d,n)->{sourceIndex=n;failedSources.clear();retries=0;reloadSource();}).show();}}).show();}
 private MediaItem media(String url){MediaItem.Builder builder=new MediaItem.Builder().setUri(url);if(item.live())builder.setLiveConfiguration(new MediaItem.LiveConfiguration.Builder().setTargetOffsetMs(12000).setMinOffsetMs(5000).setMaxOffsetMs(25000).setMinPlaybackSpeed(1f).setMaxPlaybackSpeed(1.03f).build());return builder.build();}
 private void reloadSource(){if(player==null)return;long position=item.live()?0:player.getCurrentPosition();player.setMediaItem(media(item.urls.get(sourceIndex)));if(!item.live())player.seekTo(position);bufferingSince=SystemClock.elapsedRealtime();lastProgress=bufferingSince;lastPosition=-1;player.prepare();player.play();}
 private void recover(int token,String reason){if(token!=generation||!running||errorOverlay!=null||player==null)return;if(retries<2){int delay=2000*(1<<retries++);info.setText(reason+"，重试 "+retries+"/2…");handler.postDelayed(()->{if(token==generation&&running&&player!=null&&errorOverlay==null){bufferingSince=SystemClock.elapsedRealtime();player.prepare();player.play();}},delay);return;}failedSources.add(item.urls.get(sourceIndex));for(int n=1;n<=item.urls.size();n++){int candidate=(sourceIndex+n)%item.urls.size();if(!failedSources.contains(item.urls.get(candidate))){sourceIndex=candidate;retries=0;info.setText("正在切换此频道备用源 "+(sourceIndex+1));reloadSource();return;}}showError("此内容的播放源暂时不可用，请重试或换下一项。");}
 private void switchItem(int delta){long now=SystemClock.elapsedRealtime();if(now-lastSwitch<350)return;lastSwitch=now;index=CatalogParser.wrappedIndex(index,delta,items.size());open();}
 @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getAction()==KeyEvent.ACTION_DOWN&&item!=null){int key=event.getKeyCode();if(key==KeyEvent.KEYCODE_MENU){options();return true;}if(key==KeyEvent.KEYCODE_CHANNEL_UP||key==KeyEvent.KEYCODE_MEDIA_NEXT||(item.live()&&key==KeyEvent.KEYCODE_DPAD_RIGHT&&((video!=null&&video.hasFocus()&&!video.isControllerFullyVisible())||(web!=null&&web.hasFocus())))){switchItem(1);return true;}if(key==KeyEvent.KEYCODE_CHANNEL_DOWN||key==KeyEvent.KEYCODE_MEDIA_PREVIOUS||(item.live()&&key==KeyEvent.KEYCODE_DPAD_LEFT&&((video!=null&&video.hasFocus()&&!video.isControllerFullyVisible())||(web!=null&&web.hasFocus())))){switchItem(-1);return true;}if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE&&player!=null){if(player.isPlaying())player.pause();else player.play();return true;}}return super.dispatchKeyEvent(event);}
 private void hideWebFullscreen(){if(customView!=null){android.view.ViewParent parent=customView.getParent();if(parent instanceof android.view.ViewGroup)((android.view.ViewGroup)parent).removeView(customView);customView=null;WebChromeClient.CustomViewCallback callback=customCallback;customCallback=null;if(callback!=null)callback.onCustomViewHidden();}}
 @Override public void onBackPressed(){if(customView!=null)hideWebFullscreen();else super.onBackPressed();}
 private void release(){hideWebFullscreen();handler.removeCallbacksAndMessages(null);if(player!=null){if(item!=null&&!item.live())store.position(item.id,completed?0:player.getCurrentPosition());if(video!=null)video.setPlayer(null);player.release();player=null;}if(web!=null){web.stopLoading();web.loadUrl("about:blank");web.destroy();web=null;}video=null;}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("index",index);}
 @Override protected void onStop(){running=false;generation++;release();super.onStop();}
}
